-- Read-only, after the first poll. Generated by Build-Sql.py.
SELECT 'feed|' || p.id || '|' || p.name || '|' || f.consecutive_failures || '|' || coalesce(to_char(f.last_success_at, 'HH24:MI'), 'never')
       || '|' || coalesce(left(f.last_error, 60), '-')
       || '|' || (SELECT count(*) FROM articles a WHERE a.publisher_id = p.id) || ' art'
       || '|' || (SELECT count(*) FROM articles a WHERE a.publisher_id = p.id AND a.published_at IS NULL) || ' undated'
  FROM publisher_submissions s JOIN publishers p ON p.id = s.publisher_id JOIN feeds f ON f.publisher_id = p.id
 WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-19, Build #104 Inquirer]' ORDER BY p.id;
SELECT 'future|' || count(*) FILTER (WHERE a.published_at > a.fetched_at) || ' dated after fetch|' || count(*) FILTER (WHERE a.published_at = a.fetched_at) || ' clamped to fetch time|' || count(*) || ' total' FROM articles a JOIN publisher_submissions s ON s.publisher_id = a.publisher_id WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-19, Build #104 Inquirer]';
SELECT 'ok|' || count(*) FILTER (WHERE f.last_success_at > now() - interval '30 minutes') || ' of 1'
  FROM publisher_submissions s JOIN feeds f ON f.publisher_id = s.publisher_id WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-19, Build #104 Inquirer]';
SELECT 'sample|' || p.name || '|' || to_char(a.published_at, 'YYYY-MM-DD HH24:MI') || '|fetched ' || to_char(a.fetched_at, 'HH24:MI') || '|' || left(a.headline, 70)
  FROM articles a JOIN publishers p ON p.id = a.publisher_id
 WHERE a.id IN (SELECT max(a2.id) FROM articles a2 JOIN publisher_submissions s ON s.publisher_id = a2.publisher_id WHERE s.verification_detail LIKE '%' || '[added by Claude 2026-10-19, Build #104 Inquirer]' GROUP BY a2.publisher_id);
